import { type SynapseEnhancedHttpClient, SynapseEnhancedError } from "../utils/http.ts";
import { ErrorCode } from "../utils/error-codes.ts";

export interface IPrivateChatFeatures {
    sessions: {
        available: boolean;
        max_participants?: number;
        max_duration_hours?: number;
    };
    messages: {
        available: boolean;
        max_length?: number;
        types?: string[];
        retention_days?: number;
    };
    encryption: {
        available: boolean;
        algorithm?: string;
        required: boolean;
    };
    ttl: {
        available: boolean;
        max_hours?: number;
        default_hours?: number;
    };
}

export interface IPrivateChatCapabilities {
    max_sessions_per_user: number;
    max_participants_per_session: number;
    max_message_length: number;
    supported_message_types: string[];
    encryption_required: boolean;
    retention_enabled: boolean;
    default_retention_days: number;
    features: string[];
}

export interface IPrivateChatStatusApi {
    getStatus(): Promise<IPrivateChatFeatures>;
    getCapabilities(): Promise<IPrivateChatCapabilities>;
    checkAvailability(): Promise<boolean>;
}

export class PrivateChatStatusApi implements IPrivateChatStatusApi {
    private httpClient: SynapseEnhancedHttpClient;
    private readonly baseUrl = "/private/status";

    public constructor(httpClient: SynapseEnhancedHttpClient) {
        this.httpClient = httpClient;
    }

    /**
     * Get private chat features status
     */
    public async getStatus(): Promise<IPrivateChatFeatures> {
        const response = await this.httpClient.get<{
            status: string;
            endpoint: string;
            features: IPrivateChatFeatures;
            error?: string;
        }>(this.baseUrl);

        if (response.data.status !== "ok") {
            throw new SynapseEnhancedError(
                response.data.error || "Failed to get private chat status",
                ErrorCode.UNKNOWN,
            );
        }

        if (!response.data.features) {
            throw new SynapseEnhancedError("No features data returned", ErrorCode.UNKNOWN);
        }

        return response.data.features;
    }

    /**
     * Get private chat capabilities
     */
    public async getCapabilities(): Promise<IPrivateChatCapabilities> {
        const response = await this.httpClient.get<{
            status: string;
            capabilities?: IPrivateChatCapabilities;
            error?: string;
        }>(`${this.baseUrl}/capabilities`);

        if (response.data.status !== "ok") {
            throw new SynapseEnhancedError(
                response.data.error || "Failed to get private chat capabilities",
                ErrorCode.UNKNOWN,
            );
        }

        if (!response.data.capabilities) {
            throw new SynapseEnhancedError("No capabilities data returned", ErrorCode.UNKNOWN);
        }

        return response.data.capabilities;
    }

    /**
     * Check if private chat feature is available
     */
    public async checkAvailability(): Promise<boolean> {
        try {
            const status = await this.getStatus();
            return status.sessions.available && status.messages.available && status.encryption.available;
        } catch {
            return false;
        }
    }

    /**
     * Check if encryption is required for private chats
     */
    public async isEncryptionRequired(): Promise<boolean> {
        const capabilities = await this.getCapabilities();
        return capabilities.encryption_required;
    }

    /**
     * Get maximum message length allowed
     */
    public async getMaxMessageLength(): Promise<number> {
        const capabilities = await this.getCapabilities();
        return capabilities.max_message_length;
    }

    /**
     * Get supported message types
     */
    public async getSupportedMessageTypes(): Promise<string[]> {
        const capabilities = await this.getCapabilities();
        return capabilities.supported_message_types;
    }

    /**
     * Check if a specific feature is enabled
     */
    public async isFeatureEnabled(feature: "encryption" | "retention" | "ttl"): Promise<boolean> {
        const capabilities = await this.getCapabilities();
        const featureMap: Record<string, string[]> = {
            encryption: ["encryption"],
            retention: ["retention"],
            ttl: ["ttl"],
        };

        const enabledFeatures = capabilities.features || [];
        const requiredFeatures = featureMap[feature] || [];
        return requiredFeatures.some((f) => enabledFeatures.includes(f));
    }

    /**
     * Get configuration summary
     */
    public async getConfigSummary(): Promise<{
        encryption: boolean;
        retention_days: number;
        max_participants: number;
        max_sessions: number;
    }> {
        const [capabilities] = await Promise.all([this.getCapabilities()]);

        return {
            encryption: capabilities.encryption_required,
            retention_days: capabilities.default_retention_days,
            max_participants: capabilities.max_participants_per_session,
            max_sessions: capabilities.max_sessions_per_user,
        };
    }
}
